def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive_opponents = []
    prev_bids = []
    dangerous_pressure = 0.0
    rich_alive = 0

    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            if opp.get('budget', 0) >= 300:
                rich_alive += 1
            prev = opp.get('previous_trace', {}) or {}
            bid = prev.get('bid')
            if bid is not None:
                prev_bids.append(bid)
                if bid > dangerous_pressure:
                    dangerous_pressure = bid

    if budget <= 0:
        return 0.0

    slots = max(1, int(supply // WATER_REQ))
    competitors = 1 + len(alive_opponents)
    scarcity = competitors - slots

    if not alive_opponents:
        if hp <= 2 or no_water >= 1:
            return float(min(budget, 35.0))
        return float(min(budget, 8.0))

    if prev_bids:
        top_prev = max(prev_bids)
        avg_prev = sum(prev_bids) / len(prev_bids)
    else:
        top_prev = 0.0
        avg_prev = 0.0

    urgency = 0
    if hp <= 2:
        urgency += 3
    elif hp <= 4:
        urgency += 2
    elif hp <= 6:
        urgency += 1

    if no_water >= 2:
        urgency += 3
    elif no_water >= 1:
        urgency += 2

    if scarcity >= 2:
        urgency += 2
    elif scarcity >= 1:
        urgency += 1

    if top_prev >= 100:
        urgency += 2
    elif top_prev >= 70:
        urgency += 1

    if rich_alive >= 2:
        urgency += 1

    if day >= 8:
        urgency += 1

    if urgency <= 1:
        bid = 12.0 if slots >= 2 else 18.0
    elif urgency == 2:
        bid = max(22.0, avg_prev * 0.45)
    elif urgency == 3:
        bid = max(32.0, min(48.0, top_prev * 0.55 + 4.0))
    elif urgency == 4:
        bid = max(45.0, min(68.0, top_prev * 0.72 + 3.0))
    elif urgency == 5:
        bid = max(60.0, min(88.0, top_prev * 0.82 + 4.0))
    else:
        bid = max(75.0, min(110.0, top_prev * 0.9 + 6.0))

    if hp <= 2 or no_water >= 2:
        bid = max(bid, 78.0)

    if supply >= 24 and hp >= 6 and no_water == 0:
        bid *= 0.75
    elif supply >= 21 and hp >= 5 and no_water == 0:
        bid *= 0.88

    if dangerous_pressure >= 140 and hp >= 5 and no_water == 0:
        bid *= 0.8

    reserve = 0.0
    if day <= 7:
        reserve = 35.0
    elif day <= 9:
        reserve = 15.0

    affordable = max(0.0, budget - reserve)
    if hp <= 3 or no_water >= 1:
        affordable = budget

    final_bid = min(budget, bid)
    if affordable > 0:
        final_bid = min(final_bid, affordable)
    if final_bid < 0:
        final_bid = 0.0

    if (hp <= 2 or no_water >= 1) and budget > 0:
        final_bid = max(final_bid, min(budget, 35.0))

    return float(round(final_bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    # Identify alive opponents
    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append(o)

    # If we are in critical hp, prioritize survival with a strong bid.
    my_hp = float(my_status['hp'])
    my_budget = float(my_status['budget'])

    # Reaction to yesterday bids (only immediate trace)
    yesterday_bids = []
    for o in alive_opps:
        prev = o.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            try:
                yesterday_bids.append(float(prev['bid']))
            except Exception:
                pass

    # Estimate how much water we likely need today.
    # If supply is low, winning a larger share is more valuable.
    # Use a conservative scaling based on supply range.
    # target_bid_base is between ~0.45 and ~0.85 of daily salary.
    if supply <= MIN_SUPPLY:
        target_bid_base = 0.85
    elif supply >= MAX_SUPPLY:
        target_bid_base = 0.45
    else:
        # Linear interpolation between MIN_SUPPLY and MAX_SUPPLY
        t = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)
        target_bid_base = 0.85 - 0.40 * t

    # If yesterday saw very high bids, it suggests pressure; slightly raise.
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        # If someone was bidding near/above typical salary, treat as high-pressure.
        if highest_prev_bid >= DAILY_SALARY * 0.85:
            if my_hp > 3:
                target_bid_base = max(target_bid_base, 0.70)
            else:
                target_bid_base = max(target_bid_base, 0.95)
        # If bids were generally low, we can undercut.
        elif max(yesterday_bids) <= DAILY_SALARY * 0.60:
            target_bid_base = min(target_bid_base, 0.60)

    # Convert base to bid amount; also ensure we don't exceed budget.
    bid = DAILY_SALARY * target_bid_base

    # Budget-aware cap: never bid more than we can afford.
    if my_budget <= 0:
        return 0.0
    if bid > my_budget:
        bid = my_budget

    # Ensure some minimal competitive bid if budget allows.
    # If we have enough budget, avoid bidding too low.
    min_competitive = DAILY_SALARY * 0.35
    if my_budget >= min_competitive and bid < min_competitive:
        bid = min_competitive

    # If hp is extremely low, go aggressive.
    if my_hp <= 2:
        bid = min(my_budget, DAILY_SALARY * 0.95)

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 80
    WATER_REQ = 7
    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], 10.0)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    avg_prev_bid = sum(yesterday_bids) / len(yesterday_bids) if yesterday_bids else 50.0

    if my_status['hp'] <= 3:
        bid = avg_prev_bid * 1.2
    else:
        bid = avg_prev_bid * 1.05

    return float(min(my_status['budget'], max(10.0, bid)))

